#!/bin/zsh
base="https://learn.microsoft.com/en-us"
for p in power-bi/fundamentals/desktop-getting-started power-bi/transform-model/desktop-query-overview power-bi/create-reports/desktop-ribbon power-bi/connect-data/desktop-connect-csv power-query/data-profiling-tools power-query/power-query-query-parameters power-query/data-types power-query/merge-queries-left-anti power-query/merge-queries-overview power-query/group-by power-query/unpivot-column power-query/pivot-columns power-query/add-custom-column power-query/dealing-with-errors power-query/working-with-duplicates power-query/append-queries power-query/connectors/json power-query/connectors/parquet power-query/power-query-ui power-query/filter-values power-query/replace-values power-bi/transform-model/desktop-enter-data-directly-into-desktop power-bi/transform-model/desktop-create-and-manage-relationships power-bi/transform-model/desktop-relationship-view power-bi/transform-model/dax-query-view power-bi/transform-model/desktop-date-tables power-bi/transform-model/desktop-measures power-bi/transform-model/desktop-tutorial-create-measures power-bi/transform-model/desktop-calculated-columns power-bi/transform-model/calculation-groups power-bi/create-reports/desktop-performance-analyzer power-bi/create-reports/desktop-sort-by-column power-bi/create-reports/desktop-report-themes power-bi/create-reports/power-bi-report-add-filter power-bi/visuals/power-bi-visualization-slicers power-bi/create-reports/service-reports-visual-interactions power-bi/create-reports/desktop-drillthrough power-bi/create-reports/desktop-tooltips power-bi/create-reports/desktop-bookmarks power-bi/create-reports/desktop-buttons power-bi/transform-model/desktop-visual-calculations-overview power-bi/create-reports/power-bi-create-mobile-optimized-report-about power-bi/transform-model/desktop-analytics-pane power-bi/enterprise/service-admin-rls power-bi/create-reports/desktop-conditional-table-formatting power-bi/collaborate-share/service-create-the-new-workspaces power-bi/create-reports/desktop-upload-desktop-files power-bi/collaborate-share/service-create-distribute-apps power-bi/connect-data/refresh-scheduled-refresh power-bi/create-reports/desktop-sync-slicers power-bi/create-reports/desktop-accessibility-creating-reports power-bi/transform-model/desktop-quick-measures power-bi/transform-model/desktop-modeling-view power-bi/create-reports/desktop-hierarchies power-bi/transform-model/desktop-hierarchies power-bi/connect-data/desktop-data-source-settings power-bi/enterprise/desktop-privacy-levels power-bi/visuals/power-bi-report-add-visualizations-i power-bi/create-reports/desktop-format-pane power-bi/fundamentals/desktop-latest-update fabric/fundamentals/fabric-trial fabric/fundamentals/free-trial-account-personal-email power-bi/visuals/power-bi-visualization-types-for-reports-and-q-and-a power-bi/create-reports/power-bi-dashboards-create-a-new-dashboard power-bi/create-reports/service-set-data-alerts power-bi/connect-data/service-gateway-onprem; do
  slug=$(echo $p | tr '/' '_' | tr -d '?')
  mkdir -p $slug
  curl -sfL "$base/$p" -o $slug/page.html || { echo "NO $p"; rmdir $slug 2>/dev/null; continue; }
  dir=$(dirname $p)
  for src in $(grep -o 'src="media/[^"]*"' $slug/page.html | sed 's/src="//;s/"//' | sort -u); do
    curl -sfL "$base/$dir/$src" -o "$slug/$(basename $src)" 
  done
  echo "$p $(ls $slug | wc -l)"
done
